/**
 * cert-engine.js — High-Precision Certificate Engine
 * INNOVATION HACKS GLOBAL AI HACKATHON 2026 — Community Innovation Hacks
 *
 * Renders high-fidelity, print-ready certificates at A4 landscape 300 DPI (3508 × 2480 px).
 * Features auto-scaling typography, premium futuristic styling, and instant PNG/PDF generation.
 */
(function (window) {
  'use strict';

  /* ── CANVAS RESOLUTION (A4 Landscape at 300 DPI) ── */
  const FULL_W = 3508;
  const FULL_H = 2480;

  /* ── EVENT METADATA ── */
  const EVENT_NAME = 'INNOVATION HACKS GLOBAL AI HACKATHON 2026';
  const EVENT_TAGLINE = 'BUILD • INNOVATE • IMPACT';
  const EVENT_ORGANIZER = 'COMMUNITY INNOVATION HACKS';

  /* ── PER-TEMPLATE CONFIGURATION ── */
  var CONFIGS = {
    participation: {
      nameY        : 1476,
      color        : '#000000',     // Crisp Rich Black
      titleColor   : '#06B6D4',     // Cyan
      badgeColor   : '#1E40AF',
      font         : 'Cinzel',      // Classical Roman Award Serif — distinct, prestigious, refined
      fallbackFont : 'Outfit',
      weight       : '600',         // Refined SemiBold — sharp, elegant, non-bold
      baseline     : 'alphabetic',

      startSize    : 104,
      minSize      : 44,
      maxWidth     : 2400,
      letterSpacing: 4.5
    },
    winner1: {
      nameY        : 1640,
      color        : '#D4AF37',     // Premium Gold
      titleColor   : '#F59E0B',
      badgeColor   : '#B45309',
      font         : 'Cinzel',
      fallbackFont : 'Outfit',
      weight       : '600',
      baseline     : 'middle',
      startSize    : 112,
      minSize      : 48,
      maxWidth     : 2300,
      letterSpacing: 3
    },
    winner2: {
      nameY        : 1640,
      color        : '#93C5FD',     // Ice Blue / Platinum Silver
      titleColor   : '#38BDF8',
      badgeColor   : '#0284C7',
      font         : 'Cinzel',
      fallbackFont : 'Outfit',
      weight       : '600',
      baseline     : 'middle',
      startSize    : 108,
      minSize      : 46,
      maxWidth     : 2300,
      letterSpacing: 3
    },
    winner3: {
      nameY        : 1640,
      color        : '#FDBA74',     // Bronze Amber
      titleColor   : '#FB923C',
      badgeColor   : '#C2410C',
      font         : 'Cinzel',
      fallbackFont : 'Outfit',
      weight       : '600',
      baseline     : 'middle',
      startSize    : 104,
      minSize      : 44,
      maxWidth     : 2300,
      letterSpacing: 3
    },
    judges: {
      nameY        : 1210,
      color        : '#000000',     // Crisp Rich Black
      titleColor   : '#06B6D4',
      badgeColor   : '#0E7490',
      font         : 'Cinzel',
      fallbackFont : 'Outfit',
      weight       : '600',
      baseline     : 'alphabetic',
      startSize    : 104,
      minSize      : 44,
      maxWidth     : 2200,
      letterSpacing: 4.5
    }
  };

  /* ── IMAGE LOADER ── */
  function loadImg(src) {
    return new Promise(function (resolve) {
      if (!src) return resolve(null);
      var img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = function () { resolve(img); };
      img.onerror = function () { resolve(null); };
      img.src = src;
    });
  }

  /* ── EMBEDDED GUARANTEED CROSS-PLATFORM FONT DATA (BASE64) ── */
  const CINZEL_600_B64 = 'data:font/truetype;charset=utf-8;base64,';
  const CINZEL_500_B64 = 'data:font/truetype;charset=utf-8;base64,';

  /* ── FONT READINESS (GUARANTEED CROSS-PLATFORM MOBILE & DESKTOP) ── */
  let _fontsPromise = null;
  async function ensureFonts() {
    if (_fontsPromise) return _fontsPromise;
    _fontsPromise = (async function () {
      if (typeof FontFace !== 'undefined') {
        // 1. Load Cinzel 600 (SemiBold) with multi-tier failover
        if (!document.fonts.check('600 48px "Cinzel"')) {
          let loaded = false;
          try {
            const fLocal = new FontFace('Cinzel', "url('Cinzel-SemiBold.ttf')", { weight: '600', style: 'normal' });
            const l = await fLocal.load();
            document.fonts.add(l);
            loaded = true;
          } catch (e) {}

          if (!loaded) {
            try {
              const fCdn = new FontFace('Cinzel', "url('https://fonts.gstatic.com/s/cinzel/v26/8vIU7ww63mVu7gtR-kwKxNvkNOjw-gjgTYo.ttf')", { weight: '600', style: 'normal' });
              const l = await fCdn.load();
              document.fonts.add(l);
              loaded = true;
            } catch (e) {}
          }

          if (!loaded && CINZEL_600_B64) {
            try {
              const fB64 = new FontFace('Cinzel', "url('" + CINZEL_600_B64 + "')", { weight: '600', style: 'normal' });
              const l = await fB64.load();
              document.fonts.add(l);
              loaded = true;
            } catch (e) {}
          }
        }

        // 2. Load Cinzel 500 (Medium)
        if (!document.fonts.check('500 48px "Cinzel"')) {
          let loaded = false;
          try {
            const fLocal = new FontFace('Cinzel', "url('Cinzel-Medium.ttf')", { weight: '500', style: 'normal' });
            const l = await fLocal.load();
            document.fonts.add(l);
            loaded = true;
          } catch (e) {}

          if (!loaded) {
            try {
              const fCdn = new FontFace('Cinzel', "url('https://fonts.gstatic.com/s/cinzel/v26/8vIU7ww63mVu7gtR-kwKxNvkNOjw-uTnTYo.ttf')", { weight: '500', style: 'normal' });
              const l = await fCdn.load();
              document.fonts.add(l);
              loaded = true;
            } catch (e) {}
          }

          if (!loaded && CINZEL_500_B64) {
            try {
              const fB64 = new FontFace('Cinzel', "url('" + CINZEL_500_B64 + "')", { weight: '500', style: 'normal' });
              const l = await fB64.load();
              document.fonts.add(l);
              loaded = true;
            } catch (e) {}
          }
        }

        // 3. Load Outfit 600
        if (!document.fonts.check('600 48px "Outfit"')) {
          try {
            const fOut = new FontFace('Outfit', "url('Outfit-SemiBold.ttf')", { weight: '600', style: 'normal' });
            const l = await fOut.load();
            document.fonts.add(l);
          } catch (e) {
            try {
              const fCdn = new FontFace('Outfit', "url('https://fonts.gstatic.com/s/outfit/v15/QGYyz_MVcBeNP4NjuGObqx1XmO1I4e6yC4E.ttf')", { weight: '600', style: 'normal' });
              const l = await fCdn.load();
              document.fonts.add(l);
            } catch (e2) {}
          }
        }
      }

      // Force browser font manager to load
      if (document.fonts && document.fonts.load) {
        try {
          await Promise.all([
            document.fonts.load('600 60px "Cinzel"'),
            document.fonts.load('500 60px "Cinzel"'),
            document.fonts.load('600 60px "Outfit"')
          ]);
        } catch (e) {}
      }

      if (document.fonts && document.fonts.ready) {
        try {
          await document.fonts.ready;
        } catch (e) {}
      }
    })().catch(function () {
      _fontsPromise = null;
    });
    return _fontsPromise;
  }

  /* ── AUTO-SCALING TYPOGRAPHY ── */
  function autoFontSize(ctx, text, maxW, startSz, minSz, weight, family) {
    var sz = startSz;
    ctx.font = weight + ' ' + sz + 'px "' + family + '", "Cinzel", "Times New Roman", serif';
    while (ctx.measureText(text).width > maxW && sz > minSz) {
      sz -= 2;
      ctx.font = weight + ' ' + sz + 'px "' + family + '", "Cinzel", "Times New Roman", serif';
    }
    return sz;
  }

  /* ── LETTER-SPACED TEXT RENDERER ── */
  function fillTextSpaced(ctx, text, x, y, spacing) {
    if (!spacing) { ctx.fillText(text, x, y); return; }
    var totalW = 0;
    var chars  = text.split('');
    chars.forEach(function(ch) { totalW += ctx.measureText(ch).width + spacing; });
    totalW -= spacing;
    var curX = x - totalW / 2;
    chars.forEach(function(ch) {
      ctx.fillText(ch, curX + ctx.measureText(ch).width / 2, y);
      curX += ctx.measureText(ch).width + spacing;
    });
  }

  /* ── CORE RENDER ENGINE ── */
  async function render(canvasEl, templateUrl, name, templateKey, scale) {
    var cfg = CONFIGS[templateKey] || CONFIGS.participation;
    var sc  = scale || 1;
    var W   = Math.round(FULL_W * sc);
    var H   = Math.round(FULL_H * sc);

    canvasEl.width  = W;
    canvasEl.height = H;

    var ctx = canvasEl.getContext('2d', { willReadFrequently: true });
    ctx.clearRect(0, 0, W, H);

    ctx.shadowBlur    = 0;
    ctx.shadowColor   = 'transparent';
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;

    /* Preload custom signatures if configured */
    window.CUSTOM_SIGNATURE_IMGS = window.CUSTOM_SIGNATURE_IMGS || {};
    try {
      var sigSrcOrg = (window.CUSTOM_SIGNATURES && window.CUSTOM_SIGNATURES.organizer) ||
                      (window.adminCfg && window.adminCfg.signatures && window.adminCfg.signatures.organizer) ||
                      (window.signatures && window.signatures.organizer) ||
                      localStorage.getItem('sig_organizer');
      var sigSrcDir = (window.CUSTOM_SIGNATURES && window.CUSTOM_SIGNATURES.director) ||
                      (window.adminCfg && window.adminCfg.signatures && window.adminCfg.signatures.director) ||
                      (window.signatures && window.signatures.director) ||
                      localStorage.getItem('sig_director');

      if (sigSrcOrg && (!window.CUSTOM_SIGNATURE_IMGS.organizer || window.CUSTOM_SIGNATURE_IMGS.organizer._src !== sigSrcOrg)) {
        var oImg = await loadImg(sigSrcOrg);
        if (oImg) { oImg._src = sigSrcOrg; window.CUSTOM_SIGNATURE_IMGS.organizer = oImg; }
      }
      if (sigSrcDir && (!window.CUSTOM_SIGNATURE_IMGS.director || window.CUSTOM_SIGNATURE_IMGS.director._src !== sigSrcDir)) {
        var dImg = await loadImg(sigSrcDir);
        if (dImg) { dImg._src = sigSrcDir; window.CUSTOM_SIGNATURE_IMGS.director = dImg; }
      }
    } catch(e) {}

    /* Draw background image or programmatic fallback */
    if (templateUrl) {
      var img = await loadImg(templateUrl);
      if (img) {
        ctx.drawImage(img, 0, 0, W, H);
      } else {
        _drawFuturisticBg(ctx, W, H, sc, templateKey, name);
      }
    } else {
      _drawFuturisticBg(ctx, W, H, sc, templateKey, name);
    }

    await ensureFonts();

    /* Draw Recipient Name with dynamic scaling */
    var upperName = (name || 'PARTICIPANT NAME').trim().toUpperCase();
    var maxW      = Math.round(cfg.maxWidth * sc);
    var startSz   = Math.round(cfg.startSize * sc);
    var minSz     = Math.round(cfg.minSize * sc);

    var chosenFont = cfg.font;
    var fontSize   = autoFontSize(ctx, upperName, maxW, startSz, minSz, cfg.weight, chosenFont);
    if (fontSize <= minSz && cfg.fallbackFont) {
      chosenFont = cfg.fallbackFont;
      fontSize   = autoFontSize(ctx, upperName, maxW, startSz, minSz, cfg.weight, chosenFont);
    }

    ctx.font         = cfg.weight + ' ' + fontSize + 'px "' + chosenFont + '", "Cinzel", "Times New Roman", serif';
    ctx.fillStyle    = cfg.color;
    ctx.textAlign    = 'center';
    ctx.textBaseline = cfg.baseline || 'alphabetic';

    var nameY = Math.round(cfg.nameY * sc);

    if (cfg.letterSpacing) {
      fillTextSpaced(ctx, upperName, W / 2, nameY, Math.round(cfg.letterSpacing * sc));
    } else {
      ctx.fillText(upperName, W / 2, nameY);
    }

    return Math.round(fontSize / sc);
  }

  /* ── PROGRAMMATIC PREMIUM SAAS FUTURISTIC BACKGROUND ── */
  function _drawFuturisticBg(ctx, W, H, sc, templateKey, name) {
    // 1. Dark Navy Deep Space Gradient
    var grad = ctx.createRadialGradient(W / 2, H / 2, 100 * sc, W / 2, H / 2, W * 0.7);
    grad.addColorStop(0, '#0a1532');
    grad.addColorStop(0.5, '#040b1e');
    grad.addColorStop(1, '#020617');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    // 2. Subtle Tech Grid Pattern
    ctx.strokeStyle = 'rgba(37, 99, 235, 0.07)';
    ctx.lineWidth = 1 * sc;
    var gridSpacing = 90 * sc;
    for (var x = 0; x < W; x += gridSpacing) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke();
    }
    for (var y = 0; y < H; y += gridSpacing) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
    }

    // 3. Ambient Blue/Cyan Glowing Orbs
    var orb1 = ctx.createRadialGradient(W * 0.15, H * 0.2, 0, W * 0.15, H * 0.2, 500 * sc);
    orb1.addColorStop(0, 'rgba(37, 99, 235, 0.15)');
    orb1.addColorStop(1, 'transparent');
    ctx.fillStyle = orb1;
    ctx.fillRect(0, 0, W, H);

    var orb2 = ctx.createRadialGradient(W * 0.85, H * 0.8, 0, W * 0.85, H * 0.8, 600 * sc);
    orb2.addColorStop(0, 'rgba(6, 182, 212, 0.12)');
    orb2.addColorStop(1, 'transparent');
    ctx.fillStyle = orb2;
    ctx.fillRect(0, 0, W, H);

    // 4. Clean Corporate Frame Borders
    var themeColor = '#2563EB';
    var accentColor = '#06B6D4';
    if (templateKey === 'winner1') {
      themeColor = '#D4AF37'; accentColor = '#F59E0B';
    } else if (templateKey === 'winner2') {
      themeColor = '#60A5FA'; accentColor = '#93C5FD';
    } else if (templateKey === 'winner3') {
      themeColor = '#FB923C'; accentColor = '#FDBA74';
    } else if (templateKey === 'judges') {
      themeColor = '#06B6D4'; accentColor = '#22D3EE';
    }

    // Outer Thin Frame
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.12)';
    ctx.lineWidth = 2 * sc;
    ctx.strokeRect(60 * sc, 60 * sc, W - 120 * sc, H - 120 * sc);

    // Main Accent Border
    ctx.strokeStyle = themeColor;
    ctx.lineWidth = 4 * sc;
    ctx.strokeRect(75 * sc, 75 * sc, W - 150 * sc, H - 150 * sc);

    // Inner Subtle Border
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.lineWidth = 1 * sc;
    ctx.strokeRect(90 * sc, 90 * sc, W - 180 * sc, H - 180 * sc);

    // Geometric Corner Brackets
    var offset = 75 * sc;
    var bracketLen = 60 * sc;
    ctx.strokeStyle = accentColor;
    ctx.lineWidth = 6 * sc;
    
    // Top-Left Bracket
    ctx.beginPath(); ctx.moveTo(offset, offset + bracketLen); ctx.lineTo(offset, offset); ctx.lineTo(offset + bracketLen, offset); ctx.stroke();
    // Top-Right Bracket
    ctx.beginPath(); ctx.moveTo(W - offset, offset + bracketLen); ctx.lineTo(W - offset, offset); ctx.lineTo(W - offset - bracketLen, offset); ctx.stroke();
    // Bottom-Left Bracket
    ctx.beginPath(); ctx.moveTo(offset, H - offset - bracketLen); ctx.lineTo(offset, H - offset); ctx.lineTo(offset + bracketLen, H - offset); ctx.stroke();
    // Bottom-Right Bracket
    ctx.beginPath(); ctx.moveTo(W - offset, H - offset - bracketLen); ctx.lineTo(W - offset, H - offset); ctx.lineTo(W - offset - bracketLen, H - offset); ctx.stroke();

    // 5. Header Branding: INNOVATION HACKS GLOBAL AI HACKATHON 2026
    ctx.textAlign = 'center';

    // Organizer Top Label
    ctx.fillStyle = 'rgba(148, 163, 184, 0.9)';
    ctx.font = '600 ' + Math.round(18 * sc) + 'px "Space Grotesk", "Inter", sans-serif';
    ctx.fillText(EVENT_ORGANIZER, W / 2, 210 * sc);

    // Main Event Title
    ctx.fillStyle = '#FFFFFF';
    ctx.font = '900 ' + Math.round(44 * sc) + 'px "Outfit", sans-serif';
    ctx.fillText(EVENT_NAME, W / 2, 275 * sc);

    // Tagline
    ctx.fillStyle = accentColor;
    ctx.font = '700 ' + Math.round(18 * sc) + 'px "Space Grotesk", sans-serif';
    fillTextSpaced(ctx, EVENT_TAGLINE, W / 2, 325 * sc, Math.round(4 * sc));

    // Futuristic Gradient Divider
    var divGrad = ctx.createLinearGradient(W / 2 - 350 * sc, 0, W / 2 + 350 * sc, 0);
    divGrad.addColorStop(0, 'transparent');
    divGrad.addColorStop(0.5, themeColor);
    divGrad.addColorStop(1, 'transparent');
    ctx.fillStyle = divGrad;
    ctx.fillRect(W / 2 - 350 * sc, 365 * sc, 700 * sc, 3 * sc);

    // 6. Category Title & Presentation Badge
    var mainTitle = 'CERTIFICATE OF PARTICIPATION';
    var descText = 'for actively participating in ' + EVENT_NAME + ', a global virtual hackathon organized by Community Innovation Hacks, displaying commendable ingenuity, collaborative engineering, and building solutions for global impact.';

    if (templateKey === 'winner1') {
      mainTitle = '1ST PRIZE — GRAND CHAMPION';
      descText = 'for securing 1ST PRIZE (GRAND CHAMPION) at ' + EVENT_NAME + ', demonstrating peerless innovation, exceptional technical execution, and creating a transformative real-world solution.';
    } else if (templateKey === 'winner2') {
      mainTitle = '2ND PRIZE — RUNNER-UP';
      descText = 'for securing 2ND PRIZE (RUNNER-UP) at ' + EVENT_NAME + ', delivering high technical quality, superior problem solving, and impactful innovation.';
    } else if (templateKey === 'winner3') {
      mainTitle = '3RD PRIZE — SECOND RUNNER-UP';
      descText = 'for securing 3RD PRIZE (SECOND RUNNER-UP) at ' + EVENT_NAME + ', showcasing impressive technology implementation, innovative design, and creative problem solving.';
    } else if (templateKey === 'judges') {
      mainTitle = 'CERTIFICATE OF APPRECIATION';
      descText = 'presented in sincere gratitude for their expert guidance, invaluable industry insights, and dedicated project evaluation as an Esteemed Judge at ' + EVENT_NAME + '.';
    }

    ctx.fillStyle = themeColor;
    ctx.font = '800 ' + Math.round(44 * sc) + 'px "Outfit", sans-serif';
    ctx.fillText(mainTitle, W / 2, 590 * sc);

    ctx.fillStyle = 'rgba(148, 163, 184, 0.75)';
    ctx.font = '600 ' + Math.round(20 * sc) + 'px "Space Grotesk", sans-serif';
    ctx.fillText('THIS CREDENTIAL IS PROUDLY PRESENTED TO', W / 2, 1500 * sc);

    // Horizontal Accent Line under recipient name
    var nameLineGrad = ctx.createLinearGradient(W / 2 - 450 * sc, 0, W / 2 + 450 * sc, 0);
    nameLineGrad.addColorStop(0, 'transparent');
    nameLineGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.25)');
    nameLineGrad.addColorStop(1, 'transparent');
    ctx.fillStyle = nameLineGrad;
    ctx.fillRect(W / 2 - 450 * sc, 1710 * sc, 900 * sc, 2 * sc);

    // 7. Description Paragraph (Wrapped Text)
    ctx.fillStyle = 'rgba(226, 232, 240, 0.88)';
    ctx.font = '400 ' + Math.round(25 * sc) + 'px "Inter", sans-serif';

    var words = descText.split(' ');
    var line = '';
    var maxDescW = 2100 * sc;
    var descY = 1790 * sc;
    for (var n = 0; n < words.length; n++) {
      var testLine = line + words[n] + ' ';
      var testW = ctx.measureText(testLine).width;
      if (testW > maxDescW && n > 0) {
        ctx.fillText(line.trim(), W / 2, descY);
        line = words[n] + ' ';
        descY += 46 * sc;
      } else {
        line = testLine;
      }
    }
    ctx.fillText(line.trim(), W / 2, descY);

    // 8. Footer Signatures & Official Metadata
    var footerY = 2050 * sc;

    // Left Signature: Organizer Authority
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
    ctx.lineWidth = 2 * sc;
    ctx.beginPath(); ctx.moveTo(320 * sc, footerY); ctx.lineTo(760 * sc, footerY); ctx.stroke();

    var sigOrgImg = (window.CUSTOM_SIGNATURE_IMGS && window.CUSTOM_SIGNATURE_IMGS.organizer);
    if (sigOrgImg) {
      try {
        var sw = 260 * sc, sh = 90 * sc;
        ctx.drawImage(sigOrgImg, 540 * sc - sw / 2, footerY - 95 * sc, sw, sh);
      } catch (e) { }
    } else {
      // Stylized signature curve
      ctx.strokeStyle = 'rgba(37, 99, 235, 0.85)';
      ctx.lineWidth = 3.5 * sc;
      ctx.beginPath();
      ctx.moveTo(360 * sc, footerY - 35 * sc);
      ctx.bezierCurveTo(420 * sc, footerY - 85 * sc, 490 * sc, footerY - 5 * sc, 570 * sc, footerY - 55 * sc);
      ctx.bezierCurveTo(620 * sc, footerY - 90 * sc, 690 * sc, footerY - 15 * sc, 730 * sc, footerY - 45 * sc);
      ctx.stroke();
    }

    ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
    ctx.font = '700 ' + Math.round(18 * sc) + 'px "Space Grotesk", sans-serif';
    ctx.fillText('ORGANIZING COMMITTEE', 540 * sc, footerY + 30 * sc);
    ctx.fillStyle = 'rgba(148, 163, 184, 0.75)';
    ctx.font = '500 ' + Math.round(14 * sc) + 'px "Inter", sans-serif';
    ctx.fillText('Community Innovation Hacks', 540 * sc, footerY + 58 * sc);

    // Center: Cryptographic Verification Metadata
    var certId = 'NGI-2026-' + Math.random().toString(36).substring(2, 8).toUpperCase();
    ctx.fillStyle = 'rgba(148, 163, 184, 0.85)';
    ctx.font = '600 ' + Math.round(15 * sc) + 'px "Space Mono", monospace';
    ctx.fillText('VERIFICATION ID: ' + certId, W / 2, footerY - 10 * sc);

    var issueDate = new Date().toLocaleDateString('en-IN', { year: 'numeric', month: 'long', day: 'numeric' });
    ctx.fillStyle = 'rgba(148, 163, 184, 0.65)';
    ctx.font = '500 ' + Math.round(14 * sc) + 'px "Space Mono", monospace';
    ctx.fillText('OFFICIAL ISSUE DATE: ' + issueDate, W / 2, footerY + 20 * sc);

    ctx.fillStyle = accentColor;
    ctx.font = '700 ' + Math.round(12 * sc) + 'px "Space Grotesk", sans-serif';
    ctx.fillText('GLOBAL VIRTUAL HACKATHON · UNSTOP VERIFIED', W / 2, footerY + 48 * sc);

    // Right Signature: Executive Chair
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
    ctx.lineWidth = 2 * sc;
    ctx.beginPath(); ctx.moveTo(W - 760 * sc, footerY); ctx.lineTo(W - 320 * sc, footerY); ctx.stroke();

    var sigDirImg = (window.CUSTOM_SIGNATURE_IMGS && window.CUSTOM_SIGNATURE_IMGS.director);
    if (sigDirImg) {
      try {
        var sw = 260 * sc, sh = 90 * sc;
        ctx.drawImage(sigDirImg, W - 540 * sc - sw / 2, footerY - 95 * sc, sw, sh);
      } catch (e) { }
    } else {
      // Stylized signature curve
      ctx.strokeStyle = 'rgba(6, 182, 212, 0.85)';
      ctx.lineWidth = 3.5 * sc;
      ctx.beginPath();
      ctx.moveTo(W - 720 * sc, footerY - 25 * sc);
      ctx.bezierCurveTo(W - 660 * sc, footerY - 75 * sc, W - 590 * sc, footerY - 15 * sc, W - 530 * sc, footerY - 65 * sc);
      ctx.bezierCurveTo(W - 480 * sc, footerY - 10 * sc, W - 430 * sc, footerY - 55 * sc, W - 370 * sc, footerY - 30 * sc);
      ctx.stroke();
    }

    ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
    ctx.font = '700 ' + Math.round(18 * sc) + 'px "Space Grotesk", sans-serif';
    ctx.fillText('GLOBAL DIRECTOR OF INNOVATION', W - 540 * sc, footerY + 30 * sc);
    ctx.fillStyle = 'rgba(148, 163, 184, 0.75)';
    ctx.font = '500 ' + Math.round(14 * sc) + 'px "Inter", sans-serif';
    ctx.fillText('Innovation Hacks Global Council', W - 540 * sc, footerY + 58 * sc);
  }

  /* ── PUBLIC API ── */

  /** Full 3508×2480 render (A4 300 DPI) */
  async function renderFull(canvasEl, templateUrl, name, templateKey) {
    return render(canvasEl, templateUrl, name, templateKey, 1);
  }

  /** Quarter-scale render for fast admin/portal preview */
  async function renderPreview(canvasEl, templateUrl, name, templateKey) {
    return render(canvasEl, templateUrl, name, templateKey, 0.25);
  }

  /** Download canvas as high-resolution PNG */
  function downloadPNG(canvasEl, filename) {
    var a = document.createElement('a');
    a.download = filename || 'INNOVATION-HACKS-GLOBAL-AI-HACKATHON-2026-Certificate.png';
    a.href     = canvasEl.toDataURL('image/png');
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  /** Download canvas as A4 Landscape PDF */
  function downloadPDF(canvasEl, filename) {
    try {
      var _jspdf = window.jspdf;
      var jsPDF  = _jspdf ? _jspdf.jsPDF : null;
      if (!jsPDF) throw new Error('jsPDF library not loaded');
      var pw  = canvasEl.width  / 4;
      var ph  = canvasEl.height / 4;
      var pdf = new jsPDF({ orientation: 'landscape', unit: 'px', format: [pw, ph] });
      pdf.addImage(canvasEl.toDataURL('image/png'), 'PNG', 0, 0, pw, ph);
      pdf.save(filename || 'INNOVATION-HACKS-GLOBAL-AI-HACKATHON-2026-Certificate.pdf');
    } catch (e) {
      console.error('PDF export failed:', e);
      alert('PDF export failed. Downloading high-resolution PNG instead.');
      downloadPNG(canvasEl, (filename || 'certificate').replace('.pdf', '.png'));
    }
  }

  window.CertEngine = {
    renderFull    : renderFull,
    renderPreview : renderPreview,
    downloadPNG   : downloadPNG,
    downloadPDF   : downloadPDF,
    CONFIGS       : CONFIGS,
    FULL_W        : FULL_W,
    FULL_H        : FULL_H,
    EVENT_NAME    : EVENT_NAME,
    EVENT_TAGLINE : EVENT_TAGLINE,
    EVENT_ORGANIZER : EVENT_ORGANIZER
  };

})(window);
